// Two separate cosmetic pools. Constructors and all movement/draw counters run natively.
import ghidra.app.emulator.EmulatorHelper;
import java.io.PrintWriter;
public class ZNativeCosmetic20Oracle extends ZNativeWorldEffectOracle{
 static final long SM=0x5a112e,IM=0x59e622,D=0x62dc50;
 public void run()throws Exception{try(PrintWriter out=new PrintWriter(getScriptArgs()[0])){EmulatorHelper e=new EmulatorHelper(currentProgram);try{for(int kind=0;kind<2;kind++)for(int s=0;s<512;s++){long base=kind==0?SM:IM;int stride=kind==0?6:8;byte[]pool=new byte[20*stride];for(int i=0;i<pool.length;i++)pool[i]=(byte)(i*17+s);e.writeMemory(toAddr(base),pool);int free=new int[]{0,1,19,20}[s&3];for(int i=0;i<20;i++)put(e,base+i*stride,2,i<free?100+i:-1);e.writeMemory(toAddr(0x58aaaa),new byte[16384]);put(e,0x58aaaa+(420&65520)*8+(346>>4),1,s&127);run(e,kind==0?0x461b00:0x462e00,346,420);out.println("{\"kind\":\"init\",\"scenario\":"+(kind*512+s)+",\"hash\":"+hash(e.readMemory(toAddr(base),stride*20))+"}");}
 int[][]profile={{460,9,1936,9},{3079,6,3085,8},{3018,6,3010,8},{2679,6,2673,6},{3151,6,3143,8}};int[][]points={{500,600},{-9,-600},{0,-32768},{32767,32767}};
 for(int kind=0;kind<2;kind++)for(int s=0;s<128;s++){long base=kind==0?SM:IM;int stride=kind==0?6:8;e.writeMemory(toAddr(base),new byte[stride*20]);for(int i=0;i<20;i++)put(e,base+i*stride,2,-1);for(int i=0;i<3;i++){int[]p=points[(s+i)%4];put(e,base+i*stride,2,p[0]+i*8);put(e,base+i*stride+2,2,p[1]);if(kind==0){put(e,base+i*stride+4,1,s*13+i*37);put(e,base+i*stride+5,1,(s%8)|((s>>3&1)*128));}else{put(e,base+i*stride+4,2,s*17+i*13);put(e,base+i*stride+6,1,s&1);put(e,base+i*stride+7,1,s*7);}}put(e,0x622cb8,2,s%3*12);put(e,0x622cba,2,s%5*8);put(e,0x498c24,2,320);put(e,0x498c20,2,200);int[]pr=profile[s%5];put(e,0x4d02b0,2,pr[0]);put(e,0x4d02c0,2,pr[1]);put(e,0x4d02ac,2,pr[2]);put(e,0x4d02e4,2,pr[3]);for(int tick=0;tick<32;tick++){put(e,0x622dc0,1,tick&1);put(e,0x62b3a4,4,D);run(e,kind==0?0x461970:0x464d90,0,0);int n=(int)(read(e,0x62b3a4,4)-D);out.println("{\"kind\":\"tick\",\"scenario\":"+(kind*4096+s*32+tick)+",\"hash\":"+hash(e.readMemory(toAddr(base),stride*20))+",\"drawBytes\":"+n+",\"drawHash\":"+(n==0?2166136261L:hash(e.readMemory(toAddr(D),n)))+"}");}}
 }finally{e.dispose();}}}
}
